$since = (Get-Date).AddDays(-$Days)
$skipExt = '.jpg', '.jpeg', '.png', '.bmp', '.npy', '.npz', '.exe', '.zip', '.pt', '.flag', '.pid'
$files = @(Get-ChildItem $LogSrc -Recurse -File | Where-Object {
        $_.LastWriteTime -ge $since -and ($All -or ($skipExt -notcontains $_.Extension.ToLower()))
    })
$copied = 0; $tailed = 0
foreach ($f in $files) {
    $rel = $f.FullName.Substring($LogSrc.Length).TrimStart('\', '/')
    $target = Join-Path $Dest $rel
    New-Item -ItemType Directory -Force -Path (Split-Path $target -Parent) | Out-Null
    try {
        # 服务正在写的日志也要能读: 共享读写方式打开
        $in = [System.IO.File]::Open($f.FullName, 'Open', 'Read', 'ReadWrite,Delete')
        try {
            if ($in.Length -gt $MaxBytes) {
                $target = "$target.tail"
                [void]$in.Seek(-$MaxBytes, 'End')
                $tailed++
            }
            $out = [System.IO.File]::Create($target)
            try { $in.CopyTo($out) } finally { $out.Dispose() }
        } finally { $in.Dispose() }
        $copied++
    } catch {
        Write-Host "   [跳过] $rel : $($_.Exception.Message)" -ForegroundColor Yellow
    }
