import json,glob,re,os
convs={}
for f in sorted(glob.glob('*.jsonl')+glob.glob('*.part*')):
    convs.setdefault(f.split('.')[0],[]).append(f)
info={}
for cid,files in convs.items():
    first=last=None; uu=set(); nuser=0; ncomp=0; n=0; sids=set()
    for f in sorted(files):
        with open(f,encoding='utf-8',errors='replace') as fh:
            for line in fh:
                n+=1
                # 只解析头部字段, 避免大行
                m=re.search(r'"uuid":"([0-9a-f-]{36})"',line)
                if m: uu.add(m.group(1))
                t=re.search(r'"timestamp":"([^"]+)"',line)
                if t:
                    ts=t.group(1)
                    if first is None or ts<first: first=ts
                    if last is None or ts>last: last=ts
                if '"isCompactSummary":true' in line: ncomp+=1
                s=re.search(r'"sessionId":"([0-9a-f-]{36})"',line)
                if s: sids.add(s.group(1))
                if '"type":"user"' in line and '"tool_result"' not in line and '"isMeta":true' not in line and '"isSidechain":true' not in line: nuser+=1
    info[cid]=(first,last,n,nuser,ncomp,uu,sids,sum(os.path.getsize(f) for f in files))
for cid,(a,b,n,nu,nc,uu,sids,sz) in sorted(info.items(),key=lambda x:x[1][0] or ''):
    print(cid[:8],a[:16] if a else None,'→',b[:16] if b else None,f'行={n} 用户消息≈{nu} 压缩={nc} 大小={sz//1e6:.0f}MB 内含会话号={len(sids)}')
ids=list(info)
print('--重叠(共有的消息数)')
for i in range(len(ids)):
    for j in range(i+1,len(ids)):
        c=len(info[ids[i]][5]&info[ids[j]][5])
        if c: print(ids[i][:8],ids[j][:8],c, '占', f'{c/len(info[ids[i]][5]):.0%}', f'{c/len(info[ids[j]][5]):.0%}')
EOF

